mapper.select:
select org.*, sir.role_name, sir.role_code from sys_internal_role_org org inner join sys_internal_role sir on org.role_id = sir.id where 1 = 1 and org.del_flag = '0' and sir.del_flag = '0'
and sir.role_name like concat('%',#{condition.roleName},'%')
and org.org_name like concat('%',#{condition.orgName},'%')
and org.role_id = #{condition.roleId}
and org.org_id = #{condition.orgId}
order by org.create_time desc
